import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.eclipse.rdf4j.queryrender.sparql.experimental.SparqlQueryRenderer;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.Test;

class MemoryExperimentalBlankNodeDataRenderingTest {
	@Test
	void mixedFixedAndFreshDataRoundTripsGraphAndNestedTermsAcrossRepeatedExecutions() {
		String source = "INSERT DATA { GRAPH <_:graph> { <_:fixed> <urn:p> _:fresh . "
				+ "_:fresh <urn:q> <<(<_:fixed> <urn:r> _:fresh)>> } }; "
				+ "DELETE DATA { GRAPH <_:graph> { <_:fixed> <urn:delete> \"remove\" } }";
		String rendered = new SparqlQueryRenderer()
				.render(QueryParserUtil.parseUpdate(QueryLanguage.SPARQL, source, null));
		QueryParserUtil.parseUpdate(QueryLanguage.SPARQL, rendered, null);
		var repository = new SailRepository(new MemoryStore());
		repository.init();
		try (var connection = repository.getConnection()) {
			var vf = SimpleValueFactory.getInstance();
			var fixed = vf.createBNode("fixed");
			var graph = vf.createBNode("graph");
			connection.add(fixed, vf.createIRI("urn:delete"), vf.createLiteral("remove"), graph);
			for (int execution = 0; execution < 2; execution++) {
				connection.prepareUpdate(rendered).execute();
				assertFalse(connection.hasStatement(fixed, vf.createIRI("urn:delete"), null, false, graph));
			}
			var freshNodes = new HashSet<Value>();
			try (var statements = connection.getStatements(fixed, vf.createIRI("urn:p"), null, false, graph)) {
				while (statements.hasNext()) {
					Value fresh = statements.next().getObject();
					assertInstanceOf(BNode.class, fresh);
					assertNotEquals(fixed, fresh);
					assertNotEquals(graph, fresh);
					freshNodes.add(fresh);
					TripleTerm nested = vf.createTripleTerm(fixed, vf.createIRI("urn:r"), fresh);
					assertTrue(connection.hasStatement((BNode) fresh, vf.createIRI("urn:q"), nested, false, graph));
				}
			}
			assertEquals(2, freshNodes.size());
			assertEquals(4, connection.size());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void fixedDeleteDataRetainsGraphAndNestedIdentityRoles() {
		String source = "DELETE DATA { GRAPH <_:graph> { <_:fixed> <urn:p> <<(<_:fixed> <urn:r> <_:fixed>)>> } }";
		String rendered = new SparqlQueryRenderer()
				.render(QueryParserUtil.parseUpdate(QueryLanguage.SPARQL, source, null));
		QueryParserUtil.parseUpdate(QueryLanguage.SPARQL, rendered, null);
		var repository = new SailRepository(new MemoryStore());
		repository.init();
		try (var connection = repository.getConnection()) {
			var vf = SimpleValueFactory.getInstance();
			var fixed = vf.createBNode("fixed");
			var graph = vf.createBNode("graph");
			var predicate = vf.createIRI("urn:p");
			var nested = vf.createTripleTerm(fixed, vf.createIRI("urn:r"), fixed);
			connection.add(fixed, predicate, nested, graph);
			connection.add(fixed, predicate, nested);
			connection.prepareUpdate(rendered).execute();
			assertFalse(connection.hasStatement(fixed, predicate, nested, false, graph));
			assertTrue(connection.hasStatement(fixed, predicate, nested, false, (Resource) null));
			assertEquals(1, connection.size());
		} finally {
			repository.shutDown();
		}
	}
}
